/** Z1-EVENTS (13 Nov 2026) — bring a save written before the new Zone 1 order into it without replaying or stranding anything:
 *   · Zone 1 already finished -> the Sita / Hanuman beat is marked done (never replayed)
 *   · elder brother already announced under the old order (case 10) but not fought -> he steps back until Sita's case and case 15 are done
 *   · nurse already heard by chance -> counted as heard
 *   · Guard hired at Nira's desk before the border event -> back to his gate, hire refunded, training kept for when he joins
 *   · a beggar soul still standing around after the deva revealed himself (owner e1) -> gone */
function migrateZ1Events(g, d) {
  if (d.z1EventsVersion === 1) return;
  const th = g.zoneEvents.th ||= {};
  if (g.bossCleared?.th || th.thBorderBoss === 'cleared') {
    th.sitaHanuman = 'cleared'; g.storyCaseDone.sitaledger = true; g.storyCaseDone.nurse = true;
  } else if (th.thBorderBoss && th.sitaHanuman !== 'cleared') {
    delete th.thBorderBoss; delete g.eventMapClosed['th:thBorderBoss'];
    g.bossGuarding.th = false; g.bossPending = false; if (g.bossArriveSeen) delete g.bossArriveSeen.th;
  }
  const active = g.zone === 'th';
  if (active && g.usedCases?.includes('nurse') && !g.queue.some(s => s.case === 'nurse')) g.storyCaseDone.nurse = true;
  if (active && g.guard && !guardUnlocked(g, 'th')) {
    g.guardReserve = snapshotRoster({ [g.guard.id]:g.guard })[g.guard.id];
    delete g.roster[g.guard.id]; g.guard = null; g.coin += GUARD.hire;
    g.log(`🛡️ ${GUARD.name}กลับไปเฝ้าประตูชายแดน — คืนค่าจ้าง ${GUARD.hire} เบี้ยกรรม (จะมาร่วมทีมหลังเหตุปีศาจบุกชายแดน)`, 'event');
  }
  if (active && g.devaVisits?.th) g.revealDevaSoul(null);
  if (active) g.refreshZoneEvents('th');
}

devaCaseOwed() { return this.storyCaseOwed() === 'devaMonk'; },
/** Z1-EVENTS: the Zone 1 story case that is due now ('nurse' = 5th case, 'devaMonk' = 6th, 'sitaledger' = 12th) or null. See src/z1-events.js. */
storyCaseOwed() { return owedStoryCase(this); },
/** Is this queued soul the story case that must be heard first? (It cannot be jailed, deferred or skipped.) */
storyCaseReserved(soul) {
  const owed = this.storyCaseOwed();
  return !!owed && !!soul && soul.case === owed && (!storyCaseRow(this.zone, owed)?.needsGate || this.gateBuilt());

ensureDevaCase() { this.ensureStoryCase(); this.ensureKinCases(); },
/** Z2-EVENTS: what a verdict in Zone 2 sets going. The old ape (7th case) opens Wukong's descent, Satori's father (13th) ends with the farewell,
 *  a relative of the crew ends with its choice window. Never touches the score: these are ordinary cases, judged and scored as any other. */
z2AfterVerdict(r, soul) {
  if (soul.case === 'apeelder') {
    this.storyCaseDone.apeelder = true; this.apeVerdict = r.right ? 'heaven' : 'punished';   // r.right = a pure soul sent to the gate of heaven (a pure soul at any other station is always `heaven:true, right:false`)
    this.refreshZoneEvents('asia');
    this.queueStory(r.right ? 'z2-wukong-open' : 'z2-wukong-open-b');
    this.bossPending = this.bossReady();
  } else if (soul.case === 'satorifather') {
    this.storyCaseDone.satorifather = true;
    this.queueStory(this.crewOf('kan') ? 'z2-satori-farewell' : 'z2-satori-farewell-b');
    this.refreshZoneEvents('asia'); this.bossPending = this.bossReady();
  }
  if (soul.kin) { this.kinDone[soul.kin] = { verdict:r.right ? 'heaven' : 'punished', choice:null }; this.queueNotice(`kin-after-${soul.kin}`); }
},
/** Z2-EVENTS relatives: is the crew member who owns this relative's case hired in Zone 2 right now? */
kinHired(row) { return row.crew === 'guard' ? !!this.guard : this.crew.some(c => c.k === row.crew); },
/** Each relative's case is unlocked by hiring its crew member (owner 14 Nov): the soul is put in the queue once, with its notice window.
 *  The old bandit case (A2) is an existing case: when it is in the queue, or is drawn later, the relative is attached to it. */
ensureKinCases() {
  // The relatives come after the zone's opening (the deva's test is passed): Taan is hired from the first day, his relative must not walk in before the fire is out.
  if (this.zone !== 'asia' || this.over || this.zoneEventStatus('asiaDevaTest') !== 'cleared') return;
  for (const row of Z2_KIN) {
    if (this.kinSeen[row.k] || !this.kinHired(row)) continue;
    let soul = row.existing ? this.queue.find(s => s.case === row.k && !s.kin) : null;
    // A2 already drawn (and judged) before Kuro was hired: the copy that comes now is the same soul a second time - the notice says so (kinRepeatLine)
    const repeat = !!row.existing && !soul && this.usedCases.includes(row.k);
    if (!soul) {
      const def = row.def || ALL_CASES.find(c => c.k === row.k);
      if (!def) continue;
      soul = applySoulPortrait(mkCaseSoul(def), 'asia');
      if (def.assist) soul.assist = { ...def.assist, used:false };
      this.queue.push(soul);
      if (!this.usedCases.includes(row.k)) this.usedCases.push(row.k);
    }
    soul.kin = row.k; if (repeat) soul.kinRepeat = true; this.kinSeen[row.k] = true; this.queueNotice(`kin-${row.k}`);
  }
},
/** The line that explains why the same soul stands in the queue twice (only the old bandit case A2, when it was judged before its relative was hired). '' = nothing to explain. */
kinRepeatLine(k) { return this.queue.find(s => s.kin === k)?.kinRepeat ? Z2_KIN_REPEAT_LINE : ''; },
/** Rae 7.3 follow-up: once the Gokū relative's case is closed (verdict + his closing choice), Akura says two more lines the next time he is talked to in the cave. null = nothing to say. */
kinFollowUpLines() {
  const rec = this.kinDone?.chaincmd, row = Z2_KIN_BY_KEY.chaincmd;
  if (this.zone !== 'asia' || !rec || rec.choice == null || rec.followSeen || !row?.followUp?.length) return null;
  return row.followUp;
},
kinFollowUpSeen() { const rec = this.kinDone?.chaincmd; if (rec && !rec.followSeen) { rec.followSeen = true; this.save(); } },
/** The relative's lines of the interrogation ("during") join the log at the first question, once. */
kinSpeaks(soul) {
  const row = soul?.kin && Z2_KIN_BY_KEY[soul.kin];
  if (!row || soul.kinSpoke) return;
  soul.kinSpoke = true;
  (soul.said ||= []).push(...row.during.map(text => ({ kind:'kin', text })));
},
/** Fakecup: the relative (Homura) reads the pattern on the cup and tells the truth himself - no hypnosis, no karma. */
kinAssistWhy(soul) {
  if (!soul?.assist || soul.assist.used) return soul?.assist ? 'ใช้ไปแล้วในคดีนี้' : 'ไม่มีให้ในคดีนี้';
  if (this.over || this.battle) return 'รอให้จบการต่อสู้ก่อน';
  if (!this.queue.includes(soul) || !this.caseReady(soul)) return 'ต้องมีวิญญาณมาถึงแท่นสอบสวนก่อน';
  if (!hiddenIssues(soul).length) return 'ไม่มีข้อเท็จจริงที่ยังไม่เปิดเผยเหลือแล้ว';
  return '';
},
kinAssist(soul) {
  if (this.kinAssistWhy(soul)) return null;
  const deed = soul.deeds.filter(d => !d.known)[soul.assist.reveals || 0] || soul.deeds.find(d => d.known === false);
  if (deed) { deed.known = true; deed.visible = true; }
  else revealOneIssue(soul);
  soul.assist.used = true;
  (soul.said ||= []).push(...soul.assist.lines.map((text, i) => ({ kind:i ? 'kin' : 'truth', text })));
  this.log(`🔎 ${soul.assist.by}เฉลยเอง · ไม่ต้องสะกดจิต ไม่เสียกรรม`, 'act');
  this.save(); this.onChange();
  return soul.assist;
},
/** Zone 2: the Guard has to be beaten once before he takes the post (Rae 7.1). Pressing hire opens his test; winning it hires him. */
guardTestNeeded() { return this.zone === 'asia' && !this.guard && this.zoneEventStatus('asiaGuardTest') !== 'cleared'; },
requestGuardTest() {
  if (!this.guardTestNeeded() || this.battle) return false;
  const states = this.zoneEvents.asia ||= {};
  if (states.asiaGuardTest !== 'pending' && states.asiaGuardTest !== 'active') states.asiaGuardTest = 'pending';
  this.save(); this.onChange(); return true;
},
ensureStoryCase() {
  const owed = this.storyCaseOwed();
  if (!owed) return;
  const row = storyCaseRow(this.zone, owed), def = owed === SITA_CASE.k ? SITA_CASE : row.def || ALL_CASES.find(c => c.k === owed);
  if (!def) return;

if (queued && this.queue[0] !== queued && this.caseReady(queued)) {       // drawn earlier by chance (nurse) -> it is the next case now
  this.queue.splice(this.queue.indexOf(queued), 1); this.queue.unshift(queued);
}

const soul = owed === 'sitaledger' ? mkCaseSoul(def) : applySoulPortrait(mkCaseSoul(def), this.zone);
if (owed === 'sitaledger') soul.storyHearing = true;
if (owed === 'satorifather') soul.noKanSupport = true;   // Z2-EVENTS: Satori keeps his promise not to feed the answer

if (!this.usedCases.includes(owed)) this.usedCases.push(owed);
if (owed === 'sitaledger') this.queueNotice('sita-arrive');
if (row.notice) this.queueNotice(row.notice);                  // Z2-EVENTS: the window that introduces the case

},
/** e1 (owner 13 Nov): the temple beggar IS the deva. Once he is judged he reveals himself - so no beggar soul waits for an escort, serves a
 *  sentence, queues at the heaven gate or comes back as a returning case afterwards. Pays what finish() would have paid, once. */
revealDevaSoul(soul, r = null) {
  const id = soul?.id, mine = x => x?.id === id || x?.case === 'devaMonk';
  for (const st of this.stations || []) {
    const i = st.slots.findIndex(slot => mine(slot.soul)); if (i < 0) continue;
    const [slot] = st.slots.splice(i, 1), v = r || slot.verdict;
    if (Number.isFinite(v?.coin)) this.coin += v.coin;
    this.closed.unshift({ soul:slot.soul, zone:this.zone, verdict:v, stK:st.def.k, crewK:st.crewK, intensity:slot.intensity, tick:this.tick });
    if (this.closed.length > 12) this.closed.pop();
    if (!st.slots.length) { const c = this.crewOf(st.crewK); st.crewK = null; if (c) { c.at = null; c.path = null; } }
  }
  this.transits = (this.transits || []).filter(v => {
    if (v.id !== id) return true;
    const c = this.crewOf(v.crew); if (c?.escort === id) c.escort = null;
    return false;
  });
  for (let i = (this.afterlifeWalks || []).length - 1; i >= 0; i--) {
    const walk = this.afterlifeWalks[i]; if (!mine(walk.soul) || walk.zone && walk.zone !== 'th') continue;
    this.afterlifeWalks.splice(i, 1); this.releaseEscort(walk);
  }
  this.sentences = (this.sentences || []).filter(x => !mine(x.soul) || x.zone !== 'th');
  this.held = (this.held || []).filter(x => !mine(x.soul || x));
  this.returning = (this.returning || []).filter(x => !mine(x.soul || x));
  this.queue = this.queue.filter(x => !mine(x) || this.storyCaseOwed() === 'devaMonk');
  this.courtArrivals = (this.courtArrivals || []).filter(a => this.queue.some(q => q.id === a.soulId));
},
/** Z1-EVENTS notice windows (case 5 nurse ledger, case 12 Sita arrival / Hanuman / PHANTOM-404). Persisted, shown once each by ui.js. */
queueNotice(id) { if (!this.notices.includes(id) && !this.storySeen[`notice:${id}`]) this.notices.push(id); },
ackNotice(id) {
  this.notices = this.notices.filter(n => n !== id); this.storySeen[`notice:${id}`] = true;
  if (id === 'sita-phantom' && !(this.journalNotes ||= []).includes(SITA.journal)) this.journalNotes.push(SITA.journal);
  if (id === 'z2-ape-phantom' && !(this.journalNotes ||= []).includes(Z2_JOURNAL.phantom2)) this.journalNotes.push(Z2_JOURNAL.phantom2);
  if (id === 'z2-satori-arrive') this.queueStory(this.crewOf('kan') ? 'z2-satori-ask' : 'z2-satori-ask-b');   // the notice leads into Satori's request
  this.save();
},
/** Case 12: Sita's hearing closes with choice A or B only. She is never sentenced, escorted or scored against (Rae 3.2 · Claudy's cultural default).
 *  It counts as the 12th case; Hanuman then descends (story -> notice -> the test fight sitaHanuman). */
resolveSitaCase(choice) {
  const i = this.queue.findIndex(s => s.case === SITA.caseKey), pickK = SITA.hearing.choices.find(c => c.k === choice)?.k;
  if (i < 0 || !pickK || this.battle || this.over || this.zone !== 'th') return false;
  const [soul] = this.queue.splice(i, 1);
  this.cancelCourtArrival(soul.id);
  this.casesDone++; this.zoneCases.th = (this.zoneCases.th || 0) + 1;
  this.storyCaseDone[SITA.caseKey] = true; this.sitaChoice = pickK;
  this.ledger.push({ id:soul.id, who:soul.who, tick:this.tick, over:0, short:0, karma:0, stars:5, score:null, tham:null,
    boss:'great', heaven:false, right:true, deserved:0, back:false, story:SITA.caseKey,
    archiveSoul:{ name:soul.name, who:soul.who, sp:soul.sp, case:soul.case, sex:soul.sex, deeds:[] } });
  this.log(`⚖️ ${SITA.hearing.choices.find(c => c.k === pickK).label}`, 'good');
  this.refreshZoneEvents('th');
  this.queueStory('sita-hanuman-open');
  this.bossPending = this.bossReady();
  this.save(); this.onChange();
  return true;

// Z1-EVENTS: story cases come at their own count (ensureStoryCase), never by chance - except the nurse once the story is past her (old saves)
const reserved = k => this.zone === 'th' && TH_STORY_CASE_KEYS.includes(k) && !(k === 'nurse' && storyCaseDone(this, 'nurse'));
let left = pool.filter(c => c.k !== 'devaMonk' && !c.story && !reserved(c.k) && !c.quest && !this.usedCases.includes(c.k));

if (this.zone === 'th' && TH_STORY_CASE_KEYS.includes(soul.case)) this.storyCaseDone[soul.case] = true;
if (this.zone === 'asia') this.z2AfterVerdict(r, soul);   // Z2-EVENTS: the old ape / Satori's father / the crew's relatives
// Case 5 (owner spec): the nurse's file was mis-numbered by Nira's former desk mate - said once, when the case closes.
if (this.zone === 'th' && soul.case === 'nurse' && !this.devaVisits.th) this.queueNotice('nurse-ledger');

if (walk.courier && !walk.escort) {                    // T3/1: the courier finishes where the soul does, then walks back to his post by himself
  const d = this.crewOf(walk.courier), end = walk.path?.at(-1);
  if (actorStanding(d) && end) { d.x = end[0]; d.y = end[1]; d.path = null; d.wait = 0; }
  return;
}

/** f1 (owner 13 Nov): the frontier event that is waiting at the border right now, whether or not its alert window was acknowledged.
 *  Every way into the border scene asks this, so the border boss is there the first time Yama walks down. */
breachPending() {
  if (this.battle || this.over) return null;
  for (const ev of ZONE_EVENTS[this.zone] || []) {
    if (ev.team !== 'frontier' || ev.signal || this.zoneEventStatus(ev.k) !== 'pending') continue;
    if (ev.k === 'frontierBreach' && this.devaTestStatus() !== 'cleared') continue;
    return { key:ev.k, ev };
  }
  return null;
},

// Z1-EVENTS: Hanuman descends only after Sita's hearing is closed (resolveSitaCase)
if (zone === 'th' && ev.k === 'sitaHanuman' && !this.storyCaseDone[EVENT_AFTER_CASE.sitaHanuman]) continue;
// Z2-EVENTS: Wukong comes down only once the old ape's case is judged (z2AfterVerdict)
if (zone === 'asia' && ev.k === 'asiaWukong' && !this.storyCaseDone[EVENT_AFTER_CASE.asiaWukong]) continue;

b.talk = `${ev.title.th} — ระลอก ${b.wave}/${ev.bossApart ? ev.waves.length - 1 : ev.waves.length}`;
// Z2-EVENTS (Rae 3.3 / 3.5): Nira reads the field between the waves; Akura speaks when his row comes
if (ev.k === 'asiaRageBreach') b.talk = b.wave === 2 ? Z2_TEXT.breach.afterWave1 : b.wave === 3 ? Z2_TEXT.breach.afterWave2 : b.foes.some(f => f.boss) ? Z2_TEXT.breach.lines.start : b.talk;

// The gate keeper steps out to help in this fight (cutscene cut-guard-joins-th). He stays with the team only if it is won.
if (!this.guard) {
  this.guard = actorFromLegacy({ x:GUARD_POST[0], y:GUARD_POST[1], ...(this.guardReserve || {}) }, 'th', 'guard');
  this.guard.breachGuest = true; syncRoster(this);
}

},
/** BOSS-SKILLS: the boss announces a move it will use on its next turn (warning tag on the foe + banner; the player has a whole round to answer). */
announceFoeSkill(B, foe, plan, say) {
  const sk = skillState(foe), sp = plan.skill, lang = getLang();
  sk.pending = sp.id; sk.pendingLabel = sp.name; sk.pendingAt = plan.turn;
  const text = pickText(sp.warnText, lang) || pickText(sp.name, lang);
  B.skillNotice = { phase:'warn', foeId:foe.id, skillId:sp.id, name:pickText(sp.name, lang), text };
  B.talk = text; say(`⚠ ${foe.who}: ${text}`);
},
/** BOSS-SKILLS: a boss turn with no attack in it - the charge turn of a warned move, a summon, or a heal. */
runFoeSkillTurn(B, foe, plan, say) {
  const sk = skillState(foe), sp = plan.skill, lang = getLang();
  sk.turns = plan.act;
  B.dmg.enemyHits = []; B.dmg.hitActors = []; B.dmg.skillOnly = true;
  if (plan.mode === 'warn') { this.announceFoeSkill(B, foe, plan, say); return; }
  sk.pending = null; sk.pendingLabel = null; sk.pendingAt = null; sk.used[sp.id] = (sk.used[sp.id] || 0) + 1; sk.lastUse[sp.id] = plan.turn;
  const text = pickText(sp.useText, lang);
  B.skillNotice = { phase:'use', foeId:foe.id, skillId:sp.id, name:pickText(sp.name, lang), text };
  if (text) B.talk = text;
  if (sp.kind === 'summon') {
    const zone = B.zone || this.zone;
    const made = summonFoes(B, foe, sp, { scaleHp:hp => scaleFoeHp(zone, hp, 'event'), scaleAtk:atk => scaleFoeAtk(zone, atk, 'event'), lang:getLang() });
    B.dmg.summoned = made.map(f => f.id);
    say(`${foe.who}ใช้${pickText(sp.name, lang)} — เรียก ${made.length} ตนลงสนาม`);
  } else if (sp.kind === 'heal') {
    const gain = Math.min(foe.maxHp - foe.hp, Math.max(1, Math.round(foe.maxHp * (sp.heal?.pct ?? .2))));
    foe.hp += gain; B.dmg.foeHealed = { id:foe.id, amount:gain };
    say(`${foe.who}ใช้${pickText(sp.name, lang)} — ฟื้น ${gain}`);
  }

/** QUEST-DAM-B: why the Phoenix Feather cannot go to this teammate right now ('' = it can). Battle only · a fallen teammate only · never Yama (he has the Spare Heart) · once per person per fight. */
phoenixWhy(id) {
  const b = this.battle;
  if (!b || b.over) return t('item.phoenixFeather.battleOnly');
  if (!(this.inventory.phoenixFeather > 0)) return 'ไม่มีของ / No stock';
  if (id === 'you') return t('item.phoenixFeather.noYama');
  const down = this.battleFallen().find(c => c.id === id);
  if (!down) return this.battleFallen().length ? t('item.phoenixFeather.notDown') : t('item.phoenixFeather.noneDown');   // a teammate still on his feet is not a receiver
  if (b.phoenixUsed?.[id]) return t('item.phoenixFeather.once');
  return '';
},
/** the fallen teammates a feather could still wake right now (the battle menu greys the item out when this is empty) */
phoenixTargets() {
  const b = this.battle;
  return b && !b.over ? this.battleFallen().filter(c => !b.phoenixUsed?.[c.id]) : [];
},

},
/** Z1-EVENTS (case 9): the border boss fight closes with Yama's new team move, whoever's turn it was. Free and always ready (see skillWhy). */
breachFinaleStrike() {
  const b = this.battle, boss = b?.foes.find(f => f.boss && f.hp > 0);
  if (!b || b.over || b.commandBusy || b.breachFinale !== 'ready' || !boss) return false;
  b.actorId = 'you'; b.selectedFoeId = boss.id;
  b.initiativeAction = !!b.turnQueue;
  let ok; try { ok = this.battleAct(b.finaleMove || 'teamJudgment', { actorId:'you', recipientId:'you' }); } finally { delete b.initiativeAction; }
  if (!ok) return false;
  b.commandBusy = true; b.command = null; return true;

  const ok = this.battleActCore(what, command), B = this.battle;
  if (B?.halfLine && !B.halfSaid && !B.over) {
    const boss = B.foes.find(f => f.boss && f.hp > 0);
    if (boss && boss.hp <= boss.maxHp / 2) { B.halfSaid = true; B.talk = B.halfLine; this.onChange(); }
  }
  return ok;
},
battleActCore(what, command = null) {

// Z1-EVENTS: while the border boss is held for the story's closing move, whatever is pressed IS that move (the fight can never dead-end).
if (B?.breachFinale === 'ready' && !B.over && !B.commandBusy && command?.enemyOnly !== true) {
  // The UI keeps the comic on screen until it is read (ui.js ignores commands while b.storyInterlude is set); a plain API press (tests / simulations) goes straight to the closing move.
  if (B.storyInterlude === 'th') { B.storyInterlude = null; this.storySeen.th = true; }
  if (B.storyInterlude === 'th-team-judgment-unlock') B.storyInterlude = null;
  what = B.finaleMove || 'teamJudgment'; if (command) command = { ...command, actorId:'you', recipientId:'you' };
}

} else if (featherCommand) {
  // QUEST-DAM-B (owner 15 Nov): wakes a fallen teammate at 40 % HP (HP of a teammate = morale, 0-100), costs the user's turn like any item; once per person per fight
  const hp = Math.round(100 * PHOENIX_FEATHER.heal);
  recipient.morale = hp;
  B.fallen = (B.fallen || []).filter(id => id !== recipient.id);
  B.absentActors = (B.absentActors || []).filter(id => id !== recipient.id);
  (B.phoenixUsed ||= {})[recipient.id] = true;
  if (--this.inventory.phoenixFeather <= 0) delete this.inventory.phoenixFeather;
  B.dmg.healActorId = recipient.id; B.dmg.healAmount = hp;
  B.helper = actor.id === 'you' ? null : { ...actor, lunge:false };
  B.talk = t('item.phoenixFeather.say', { name:recipient.name });
  say(B.talk);
